// Helpers to build structured control flow

def sigToBlockType(sig: FunctionType): BlockType = sig match {
  case FunctionType(Nil, Nil) =>
    BlockType.ValueType()
  case FunctionType(Nil, resultType :: Nil) =>
    BlockType.ValueType(resultType)
  case _ =>
    BlockType.FunctionType(moduleBuilder.functionTypeToTypeID(sig))
}

private def toBlockType[A](value: A)(implicit blockTypeLike: BlockTypeLike[A]): BlockType =
  blockTypeLike.toBlockType(this, value)

private def ifThenElseWith[A](blockTypeLike: A)(thenp: => Unit)(elsep: => Unit)(
    implicit ev: BlockTypeLike[A]): Unit = {
  instrs += If(toBlockType(blockTypeLike))
  thenp
  instrs += Else
  elsep
  instrs += End
}

def ifThenElse(blockType: BlockType)(thenp: => Unit)(elsep: => Unit): Unit =
  ifThenElseWith(blockType)(thenp)(elsep)

def ifThenElse(resultType: Type)(thenp: => Unit)(elsep: => Unit): Unit =
  ifThenElseWith(resultType)(thenp)(elsep)

def ifThenElse(sig: FunctionType)(thenp: => Unit)(elsep: => Unit): Unit =
  ifThenElseWith(sig)(thenp)(elsep)

def ifThenElse(resultTypes: List[Type])(thenp: => Unit)(elsep: => Unit): Unit =
  ifThenElseWith(resultTypes)(thenp)(elsep)

def ifThenElse()(thenp: => Unit)(elsep: => Unit): Unit =
  ifThenElseWith(BlockType.ValueType())(thenp)(elsep)

private def ifThenWith[A](blockTypeLike: A)(thenp: => Unit)(
    implicit ev: BlockTypeLike[A]): Unit = {
  instrs += If(toBlockType(blockTypeLike))
  thenp
  instrs += End
}

def ifThen(blockType: BlockType)(thenp: => Unit): Unit =
  ifThenWith(blockType)(thenp)

def ifThen(sig: FunctionType)(thenp: => Unit): Unit =
  ifThenWith(sig)(thenp)

def ifThen(resultTypes: List[Type])(thenp: => Unit): Unit =
  ifThenWith(resultTypes)(thenp)

def ifThen()(thenp: => Unit): Unit =
  ifThenWith(BlockType.ValueType())(thenp)

private def blockWith[B, A](blockTypeLike: B)(body: LabelID => A)(
    implicit ev: BlockTypeLike[B]): A = {
  val label = genLabel()
  instrs += Block(toBlockType(blockTypeLike), Some(label))
  val result = body(label)
  instrs += End
  result
}

def block[A](blockType: BlockType)(body: LabelID => A): A =
  blockWith(blockType)(body)

def block[A](resultType: Type)(body: LabelID => A): A =
  blockWith(resultType)(body)

def block[A]()(body: LabelID => A): A =
  blockWith(BlockType.ValueType())(body)

def block[A](sig: FunctionType)(body: LabelID => A): A =
  blockWith(sig)(body)

def block[A](resultTypes: List[Type])(body: LabelID => A): A =
  blockWith(resultTypes)(body)

private def loopWith[B, A](blockTypeLike: B)(body: LabelID => A)(
    implicit ev: BlockTypeLike[B]): A = {
  val label = genLabel()
  instrs += Loop(toBlockType(blockTypeLike), Some(label))
  val result = body(label)
  instrs += End
  result
}

def loop[A](blockType: BlockType)(body: LabelID => A): A =
  loopWith(blockType)(body)

def loop[A](resultType: Type)(body: LabelID => A): A =
  loopWith(resultType)(body)

def loop[A]()(body: LabelID => A): A =
  loopWith(BlockType.ValueType())(body)

def loop[A](sig: FunctionType)(body: LabelID => A): A =
  loopWith(sig)(body)

def loop[A](resultTypes: List[Type])(body: LabelID => A): A =
  loopWith(resultTypes)(body)

def whileLoop()(cond: => Unit)(body: => Unit): Unit = {
  loop() { loopLabel =>
    cond
    ifThen() {
      body
      instrs += Br(loopLabel)
    }
  }
}

private def tryTableWith[B, A](blockTypeLike: B)(clauses: List[CatchClause])(body: => A)(
    implicit ev: BlockTypeLike[B]): A = {
  instrs += TryTable(toBlockType(blockTypeLike), clauses)
  val result = body
  instrs += End
  result
}

def tryTable[A](blockType: BlockType)(clauses: List[CatchClause])(body: => A): A =
  tryTableWith(blockType)(clauses)(body)

def tryTable[A](resultType: Type)(clauses: List[CatchClause])(body: => A): A =
  tryTableWith(resultType)(clauses)(body)

def tryTable[A]()(clauses: List[CatchClause])(body: => A): A =
  tryTableWith(BlockType.ValueType())(clauses)(body)

def tryTable[A](sig: FunctionType)(clauses: List[CatchClause])(body: => A): A =
  tryTableWith(sig)(clauses)(body)

def tryTable[A](resultTypes: List[Type])(clauses: List[CatchClause])(body: => A): A =
  tryTableWith(resultTypes)(clauses)(body)

private trait BlockTypeLike[-A] {
  def toBlockType(functionBuilder: FunctionBuilder, value: A): BlockType
}

private implicit object BlockTypeIsBlockType extends BlockTypeLike[BlockType] {
  def toBlockType(functionBuilder: FunctionBuilder, value: BlockType): BlockType =
    value
}

private implicit object TypeIsBlockType extends BlockTypeLike[Type] {
  def toBlockType(functionBuilder: FunctionBuilder, value: Type): BlockType =
    BlockType.ValueType(value)
}

private implicit object FunctionTypeIsBlockType extends BlockTypeLike[FunctionType] {
  def toBlockType(functionBuilder: FunctionBuilder, value: FunctionType): BlockType =
    functionBuilder.sigToBlockType(value)
}

private implicit object ResultTypesAreBlockType extends BlockTypeLike[List[Type]] {
  def toBlockType(functionBuilder: FunctionBuilder, value: List[Type]): BlockType =
    functionBuilder.sigToBlockType(FunctionType(Nil, value))
}

